/bin/bash -lc "node <<'NODE'
const base = 'http://localhost:8080';
const pause = ms => new Promise(r => setTimeout(r, ms));
let token = null;
let tokenRefreshes = 0;
let rateLimits = 0;

function retryMs(res, body) {
  const h = res.headers.get('retry-after');
  if (h) {
    const seconds = Number(h);
    if (Number.isFinite(seconds)) return Math.ceil(seconds * 1000);
    const date = Date.parse(h);
    if ("'!Number.isNaN(date)) return Math.max(0, date - Date.now());
  }
  if (body && typeof body === '"'object') {
    for (const key of ['retry_after_ms', 'retry_after', 'retryAfter']) {
      if (typeof body[key] === 'number') return key.endsWith('_ms') ? Math.ceil(body[key]) : Math.ceil(body[key] * 1000);
    }
  }
  return 1000;
}

async function raw(path, opts = {}) {
  for (;;) {
    let res;
    try {
      res = await fetch(base + path, opts);
    } catch (_) {
      await pause(1000);
      continue;
    }
    const body = await res.json().catch(() => null);
    if (res.status === 429) {
      rateLimits++;
      await pause(retryMs(res, body));
      continue;
    }
    if (res.status >= 500) {
      await pause(1000);
      continue;
    }
    return {res, body};
  }
}

async function getToken() {
  const {res, body} = await raw('/token', {method: 'POST'});
  if ("'!res.ok || !body?.token) throw new Error('"'Unable to obtain token: HTTP ' + res.status);
  token = [REDACTED_SECRET]
  tokenRefreshes++;
}

async function authed(path) {
  for (;;) {
    if ("'!token) await getToken();
    const {res, body} = await raw(path, {headers: {Authorization: '"'Bearer ' + token}});
    if (res.status === 401) { token = null; continue; }
    if ("'!res.ok) throw new Error(path + '"': HTTP ' + res.status);
    return body;
  }
}

(async () => {
  const ids = new Set();
  const orders = [];
  let duplicatesSkipped = 0;
  let page = 1;
  let totalPages = null;
  while (totalPages === null || page <= totalPages) {
    const listing = await authed('/orders?page=' + page);
    if ("'!Array.isArray(listing.items) || !Number.isInteger(listing.total_pages)) throw new Error('"'Invalid listing response');
    totalPages = listing.total_pages;
    for (const order of listing.items) {
      if (ids.has(order.id)) { duplicatesSkipped++; continue; }
      ids.add(order.id);
      if (order.status "'!== '"'shipped') continue;
      const placed = new Date(order.placed_at);
      if (Number.isNaN(placed.valueOf())) throw new Error('Invalid timestamp on ' + order.id);
      if (placed >= new Date('2025-03-01T00:00:00.000Z') && placed < new Date('2025-06-01T00:00:00.000Z')) orders.push(order);
    }
    page++;
  }

  const customers = new Map();
  for (const customerId of new Set(orders.map(o => o.customer_id))) {
    const customer = await authed('/customers/' + encodeURIComponent(customerId));
    if ("'!Number.isInteger(customer.discount_pct) || !['"'north','south','east','west'].includes(customer.region)) throw new Error('Invalid customer ' + customerId);
    customers.set(customerId, customer);
  }
  const byRegion = {north: 0, south: 0, east: 0, west: 0};
  for (const order of orders) {
    const c = customers.get(order.customer_id);
    // integer half-up rounding for non-negative cent amounts
    const discounted = Math.floor((order.amount_cents * (100 - c.discount_pct) + 50) / 100);
    byRegion[c.region] += discounted;
  }
  const total = Object.values(byRegion).reduce((a, b) => a + b, 0);
  console.log(JSON.stringify({total_cents: total, order_count: orders.length, duplicates_skipped: duplicatesSkipped, by_region: byRegion}));
  console.error(JSON.stringify({pages: totalPages, unique_listings: ids.size, customer_cache: customers.size, token_refreshes: tokenRefreshes, rate_limits: rateLimits}));
})().catch(err => { console.error(err.stack || err); process.exit(1); });
NODE"

